    include: { author: true },
  });
  return NextResponse.json({
    data: posts,
    meta: { version: 2 },
  });
}

// lib/versioning.ts
export function getAPIVersion(request: Request): string {
  const accept = request.headers.get("accept") ?? "";
  const match = accept.match(/application\/vnd\.myapi\+(\d+)/);
  return match?.[1] ?? "1";
}

// app/api/posts/route.ts
export async function GET(request: Request) {
  const version = getAPIVersion(request);

  if (version === "2") {
    const posts = await db.post.findMany({ include: { author: true } });
    return NextResponse.json({ data: posts, meta: { version: 2 } });
  }

  const posts = await db.post.findMany();
  return NextResponse.json({ posts });
}

const DEPRECATED_VERSIONS = new Set(["1"]);

export async function GET(request: Request) {
  const version = getAPIVersion(request);
  const response = version === "2"
    ? NextResponse.json({ data: posts, meta: { version: 2 } })
    : NextResponse.json({ posts });

  if (DEPRECATED_VERSIONS.has(version)) {
    response.headers.set(
      "Sunset",
      new Date(Date.now() + 90 * 24 * 60 * 60 * 1000).toISOString()
    );
    response.headers.set(
      "Link",
      "<https://yourdomain.com/api/v2/posts>; rel=\"successor-version\""
    );
  }

  return response;
}
